import urwid
import sys
import os

class LazyFileWalker(urwid.ListWalker):
    def __init__(self, filename):
        self.filename = filename
        self.lines = []
        self.focus = 0
        self.file_size = os.path.getsize(filename)
        self.file = open(filename, 'r+', encoding='utf-8')
        self.line_offsets = [0]
        self._build_offsets()
        self._load_lines()

    def _build_offsets(self):
        # Build line offsets for lazy loading
        self.file.seek(0)
        offset = 0
        while True:
            line = self.file.readline()
            if not line:
                break
            offset += len(line.encode('utf-8'))
            self.line_offsets.append(offset)
        self.file.seek(0)

    def _load_lines(self):
        # Load all lines into memory for editing
        self.file.seek(0)
        self.lines = [line.rstrip('\n') for line in self.file.readlines()]
        if not self.lines:
            self.lines = ['']

    def get_focus(self):
        return self._get_at_pos(self.focus)

    def set_focus(self, position):
        self.focus = position
        self._modified()

    def get_next(self, position):
        if position + 1 >= len(self.lines):
            return None, None
        return self._get_at_pos(position + 1)

    def get_prev(self, position):
        if position - 1 < 0:
            return None, None
        return self._get_at_pos(position - 1)

    def _get_at_pos(self, pos):
        if pos < 0 or pos >= len(self.lines):
            return None, None
        return LineEdit(self, pos), pos

    def save(self):
        with open(self.filename, 'w', encoding='utf-8') as f:
            for line in self.lines:
                f.write(line + '\n')

class LineEdit(urwid.Edit):
    def __init__(self, walker, pos):
        super().__init__('', walker.lines[pos])
        self.walker = walker
        self.pos = pos
        self.set_edit_text(walker.lines[pos])
        self.set_edit_pos(len(walker.lines[pos]))

    def keypress(self, size, key):
        walker = self.walker
        pos = self.pos
        edit_text = self.edit_text
        edit_pos = self.edit_pos

        if key == 'left':
            if edit_pos > 0:
                self.set_edit_pos(edit_pos - 1)
            elif pos > 0:
                walker.set_focus(pos - 1)
                walker._modified()
        elif key == 'right':
            if edit_pos < len(edit_text):
                self.set_edit_pos(edit_pos + 1)
            elif pos < len(walker.lines) - 1:
                walker.set_focus(pos + 1)
                walker._modified()
        elif key == 'up':
            if pos > 0:
                walker.set_focus(pos - 1)
                walker._modified()
        elif key == 'down':
            if pos < len(walker.lines) - 1:
                walker.set_focus(pos + 1)
                walker._modified()
        elif key == 'backspace':
            if edit_pos > 0:
                self.set_edit_text(edit_text[:edit_pos - 1] + edit_text[edit_pos:])
                self.set_edit_pos(edit_pos - 1)
                walker.lines[pos] = self.edit_text
            elif pos > 0:
                prev_line = walker.lines[pos - 1]
                walker.lines[pos - 1] = prev_line + edit_text
                del walker.lines[pos]
                walker.set_focus(pos - 1)
                walker._modified()
        elif key == 'delete':
            if edit_pos < len(edit_text):
                self.set_edit_text(edit_text[:edit_pos] + edit_text[edit_pos + 1:])
                walker.lines[pos] = self.edit_text
            elif pos < len(walker.lines) - 1:
                self.set_edit_text(edit_text + walker.lines[pos + 1])
                walker.lines[pos] = self.edit_text
                del walker.lines[pos + 1]
                walker._modified()
        elif key == 'enter':
            new_line = edit_text[edit_pos:]
            self.set_edit_text(edit_text[:edit_pos])
            walker.lines[pos] = self.edit_text
            walker.lines.insert(pos + 1, new_line)
            walker.set_focus(pos + 1)
            walker._modified()
        else:
            res = super().keypress(size, key)
            walker.lines[pos] = self.edit_text
            return res
        walker.lines[pos] = self.edit_text

class TextEditor:
    PALETTE = [
        ('footer', 'black', 'light gray'),
        ('body', 'default', 'default'),
        ('focus', 'black', 'light cyan'),
    ]

    FOOTER_TEXT = [
        ('footer', " Ctrl+S: Save  Ctrl+Q: Quit  Arrows: Move  Enter: New Line  Backspace/Delete: Remove/Join/Split Lines ")
    ]

    def __init__(self, filename):
        self.walker = LazyFileWalker(filename)
        self.listbox = urwid.ListBox(self.walker)
        self.footer = urwid.AttrMap(urwid.Text(self.FOOTER_TEXT), 'footer')
        self.frame = urwid.Frame(urwid.AttrMap(self.listbox, 'body'), footer=self.footer)
        self.filename = filename

    def unhandled_input(self, key):
        if key in ('ctrl s',):
            self.walker.save()
            self.footer.original_widget.set_text([('footer', " Saved! ")] + self.FOOTER_TEXT)
        elif key in ('ctrl q',):
            raise urwid.ExitMainLoop()
        else:
            self.footer.original_widget.set_text(self.FOOTER_TEXT)

    def run(self):
        loop = urwid.MainLoop(self.frame, self.PALETTE, unhandled_input=self.unhandled_input)
        loop.run()

def main():
    if len(sys.argv) != 2:
        print("Usage: python editor.py <filename>")
        sys.exit(1)
    filename = sys.argv[1]
    if not os.path.exists(filename):
        open(filename, 'w').close()
    editor = TextEditor(filename)
    editor.run()

if __name__ == '__main__':
    main()
